sql.where:
F.QSTNR_TYPE_CD = #{qstnrTypeCd}
AND F.DEL_DT IS NULL

	AND F.EVL_SE_CD = #{evlSeCd}


	AND DATE(F.REG_DT) >= #{startRegYmd}


	AND DATE(F.REG_DT) <= #{endRegYmd}


	AND F.QSTNR_NM LIKE CONCAT('%', #{searchKeyword}, '%')

mapper.select:
SELECT
FROM EDU_QSTNR_MST F
ORDER BY F.REG_DT DESC, F.QSTNR_SN DESC LIMIT #{offset}, #{limit}

SELECT

FROM EDU_QSTNR_MST F
WHERE F.QSTNR_SN = #{qstnrSn}
AND F.QSTNR_TYPE_CD = #{qstnrTypeCd}
AND F.DEL_DT IS NULL
